import type {
  Equipment,
  Exercise,
  ExerciseKind,
  FigureGear,
  FigureTemplate,
  MuscleGroup,
} from './exercises';

/**
 * Extended, curated movement catalog.
 *
 * Names and aliases intentionally include the language people use in gyms,
 * classes, and videos. Every movement remains editable through the workout
 * logger; this file is data-only so the same catalog can be sent to Watch.
 */
function movement(
  id: string,
  name: string,
  primaryMuscle: MuscleGroup,
  secondaryMuscles: MuscleGroup[],
  equipment: Equipment,
  kind: ExerciseKind,
  template: FigureTemplate,
  gear: FigureGear,
  met: number,
  setup: string,
  action: string,
  tip: string,
  aliases: string[] = [],
): Exercise {
  return {
    id,
    name,
    aliases,
    primaryMuscle,
    secondaryMuscles,
    equipment,
    kind,
    template,
    gear,
    met,
    instructions: [setup, action],
    tips: [tip],
  };
}

